CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE receiver_driver AS ENUM ('rtl_sdr', 'airspy', 'sdrplay', 'simulator');
CREATE TYPE system_kind AS ENUM ('p25_trunked', 'p25_conventional', 'nfm_conventional');
CREATE TYPE call_state AS ENUM ('active', 'complete', 'failed');
CREATE TYPE encryption_state AS ENUM ('clear', 'encrypted', 'unknown');
CREATE TABLE configuration_revisions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, revision bigint NOT NULL UNIQUE, actor_id uuid, document jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), activated_at timestamptz);
CREATE TABLE receivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL, driver receiver_driver NOT NULL, serial text NOT NULL, enabled boolean NOT NULL DEFAULT true, settings jsonb NOT NULL DEFAULT '{}'::jsonb, UNIQUE (driver, serial));
CREATE TABLE radio_systems (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind system_kind NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sites (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), system_id uuid NOT NULL REFERENCES radio_systems(id) ON DELETE CASCADE, name text NOT NULL, control_channels_hz bigint[] NOT NULL DEFAULT '{}', latitude double precision, longitude double precision);
CREATE TABLE talkgroups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), system_id uuid NOT NULL REFERENCES radio_systems(id) ON DELETE CASCADE, decimal_id integer NOT NULL CHECK (decimal_id >= 0), alpha_tag text NOT NULL, description text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Other', priority smallint NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true, record boolean NOT NULL DEFAULT true, public_allowed boolean NOT NULL DEFAULT false, retention_days integer CHECK (retention_days IS NULL OR retention_days > 0), UNIQUE (system_id, decimal_id));
CREATE TABLE calls (id uuid PRIMARY KEY, system_id uuid NOT NULL REFERENCES radio_systems(id), site_id uuid REFERENCES sites(id), talkgroup_id uuid REFERENCES talkgroups(id), frequency_hz bigint NOT NULL, tdma_slot smallint CHECK (tdma_slot IS NULL OR tdma_slot IN (0, 1)), source_radio_id integer, state call_state NOT NULL, encryption encryption_state NOT NULL DEFAULT 'unknown', signal_dbfs real, started_at timestamptz NOT NULL, ended_at timestamptz, transcript text, transcript_provenance jsonb, summary text, location jsonb, audio_object_key text, audio_content_type text, audio_duration_ms bigint, protected boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX calls_started_at_idx ON calls (started_at DESC);
CREATE INDEX calls_talkgroup_started_idx ON calls (talkgroup_id, started_at DESC);
CREATE INDEX calls_location_gin_idx ON calls USING gin (location);
CREATE TABLE publication_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, delay_seconds integer NOT NULL DEFAULT 120 CHECK (delay_seconds BETWEEN 0 AND 86400), expose_transcripts boolean NOT NULL DEFAULT false, expose_radio_ids boolean NOT NULL DEFAULT false, expose_precise_locations boolean NOT NULL DEFAULT false, talkgroup_ids uuid[] NOT NULL DEFAULT '{}', CHECK (NOT enabled OR cardinality(talkgroup_ids) > 0));
INSERT INTO publication_policies (name) VALUES ('default');
CREATE TABLE job_outbox (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kind text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, last_error text, UNIQUE (kind, aggregate_id));
CREATE INDEX job_outbox_ready_idx ON job_outbox (available_at) WHERE completed_at IS NULL;
CREATE TABLE audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid, action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, before_value jsonb, after_value jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
